def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    chi = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    total = sum(occ)
    if total <= 0:
        return 0.0
    value = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            a = radii[i]
            b = radii[j]
            x = chi[i]
            y = chi[j]
            if a is not None and b is not None and a > 0 and b > 0 and x is not None and y is not None:
                if d <= 1.25 * (a + b):
                    value += occ[i] * occ[j] * (1.0 - exp(-0.25 * (x - y) ** 2))
    return 0.5 * value / total

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    eligible = [r is not None and r > 0 for r in radii]
    total = sum(occ[i] for i in range(n) if eligible[i])
    if total <= 0:
        return 0.0
    coordination = [0.0] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            if eligible[i] and eligible[j] and d <= 1.25 * (radii[i] + radii[j]):
                coordination[i] += occ[j]
    mean = sum(occ[i] * coordination[i] for i in range(n) if eligible[i]) / total
    return sum(occ[i] * (coordination[i] - mean) ** 2 for i in range(n) if eligible[i]) / total

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    nearest = [None] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6 and occ[j] > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                ratio = d / (a + b)
                if nearest[i] is None or ratio < nearest[i]:
                    nearest[i] = ratio
    total = sum(occ[i] for i in range(n) if nearest[i] is not None)
    return sum(occ[i] * nearest[i] for i in range(n) if nearest[i] is not None) / total if total > 0 else 0.0

