def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    elements = [t.get('element') for t in sites]
    radii = [(props.get(e) or {}).get('covalent_radius_A') for e in elements]
    groups = [(props.get(e) or {}).get('group') for e in elements]
    eligible = [groups[i] is not None and 15 <= groups[i] <= 17 and radii[i] is not None and radii[i] > 0 for i in range(n)]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    count = [0] * n
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6 and occ[j] > 0:
            if eligible[i] and eligible[j] and elements[i] == elements[j]:
                if d <= 1.15 * (radii[i] + radii[j]):
                    count[i] += 1
    total = sum(occ[i] for i in range(n) if eligible[i])
    terminal = sum(occ[i] for i in range(n) if eligible[i] and count[i] == 1)
    return terminal / total if total > 0 else 0.0

