def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    n = len(sites)
    props = s.get('element_properties') or {}
    elements = [t.get('element') for t in sites]
    radii = [(props.get(e) or {}).get('covalent_radius_A') for e in elements]
    occ = [max(0.0, t.get('occupancy') if t.get('occupancy') is not None else 1.0) for t in sites]
    amounts = {}
    for i in range(n):
        if radii[i] is not None and radii[i] > 0:
            e = elements[i]
            amounts[e] = amounts.get(e, 0.0) + occ[i]
    occupied = sum(amounts.values())
    if occupied <= 0:
        return 0.0
    total = 0.0
    same = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and 0 < d <= 6:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0 and d <= 1.25 * (a + b):
                w = occ[i] * occ[j]
                total += w
                if elements[i] == elements[j]:
                    same += w
    if total <= 0:
        return 0.0
    baseline = sum((amount / occupied) ** 2 for amount in amounts.values())
    return same / total - baseline

def feature(s):
    if not s:
        return 0.0
    props = s.get('element_properties') or {}
    total = 0.0
    demand = 0.0
    for site in s.get('sites') or []:
        o = site.get('occupancy')
        o = max(0.0, o if o is not None else 1.0)
        total += o
        group = (props.get(site.get('element')) or {}).get('group')
        if group is None:
            continue
        if 15 <= group <= 17:
            demand += o * (18.0 - group)
        elif group == 1 or group == 2:
            demand -= o * group
        elif group == 13:
            demand -= 3.0 * o
    return demand / total if total > 0 else 0.0
